    // INCHI✔️✔️:         n1 = n2;
    // INCHI✔️✔️:     }
    // INCHI✔️✔️:     while (at[n1].valence == 2 && !at[n1].num_H && nLenCumulene < MAX_CUMULENE_LEN + 2 &&
    // INCHI✔️✔️:            bCanAtomBeMiddleAllene( at[n1].elname, at[n1].charge, at[n1].radical ));
    // INCHI✔️✔️:     return RI_ERR_SYNTAX; /* failed */
    // INCHI✔️✔️:
    // INCHI✔️✔️: found:
    // INCHI✔️✔️:     if (nLenCumulene == 2)
    // INCHI✔️✔️:     {
    // INCHI✔️✔️:         bond_type = BOND_TYPE_STEREO; /* double bond or alternating bond */
    // INCHI✔️✔️:     }
    // INCHI✔️✔️:     else
    // INCHI✔️✔️:     {
    // INCHI✔️✔️:         bond_type = BOND_TYPE_DOUBLE; /* cumulene or allene */
    // INCHI✔️✔️:     }
    // INCHI✔️✔️:
    // INCHI✔️✔️:     for (j = 1; j < nLenCumulene; j++)
    // INCHI✔️✔️:     {
    // INCHI✔️✔️:         /* if bond_type = BOND_TYPE_DOUBLE then increments at->cham_bonds_valence: */
    // INCHI✔️✔️:         /* at->cham_bonds_valence += BOND_TYPE_DOUBLE-BOND_TYPE_SINGLE */
    // INCHI✔️✔️:         if (0 > ( ret = set_bond_type( at, (AT_NUMB) nCumulene[j - 1], (AT_NUMB) nCumulene[j], bond_type ) )) /* djb-rwth: ignoring LLVM warning: variable used to store function return value */
