    // INCHI✔️✔️:     if (!st || !at[i1].p_parity)
    // INCHI✔️✔️:     {
    // INCHI✔️✔️:         m1 = 0;
    // INCHI✔️✔️:         p_parity = st ? &st[i1].p_parity : &at[i1].p_parity;
    // INCHI✔️✔️:         p_orig_at_num = st ? st[i1].p_orig_at_num : at[i1].p_orig_at_num;
    // INCHI✔️✔️:
    // INCHI✔️✔️:         tot_num_neigh = at[i1].valence + at[i1].num_H;
    // INCHI✔️✔️:         if (tot_num_neigh == MAX_NUM_STEREO_ATOM_NEIGH - 1)
    // INCHI✔️✔️:         {
    // INCHI✔️✔️:             /* only 3 neighbors: the atom itself is the first neighbor */
    // INCHI✔️✔️:             p_orig_at_num[m1++] = at[i1].orig_at_number;
    // INCHI✔️✔️:         }
