                    && neighbor.num_H == 0
                    && neighbor.chem_bonds_valence == 4
                    && neighbor.charge == 0
                    && neighbor.radical == 0
                    && pVA[neighbor_index].cNumValenceElectrons == 4
                    && cn_index > 0
