#[derive(Clone, Copy, Default)]
struct MobileGroupCount {
    group_number: i32,
    count: i32,
}

fn bns_edge_index(
    heap: &SourceHeap,
    vertices: &[BNS_VERTEX],
    vertex: usize,
    neighbor_order: usize,
) -> Result<usize, SourceHeapError> {
    let vertex = vertices.get(vertex).ok_or(SourceHeapError::PointerOutOfBounds)?;
    let edge = *heap
        .slice(vertex.iedge.as_const())?
        .get(neighbor_order)
        .ok_or(SourceHeapError::PointerOutOfBounds)?;
    usize::try_from(edge).map_err(|_| SourceHeapError::PointerOutOfBounds)
}

fn opposite_vertex(edge: &BNS_EDGE, vertex: usize) -> Result<usize, SourceHeapError> {
    usize::try_from(i32::from(edge.neighbor12) ^ vertex as i32).map_err(|_| SourceHeapError::PointerOutOfBounds)
}

fn bns_direct_edge_index(
    heap: &SourceHeap,
    bns: &BN_STRUCT,
    vertex: usize,
    neighbor_order: usize,
) -> Result<usize, SourceHeapError> {
    let iedge = heap
        .slice(bns.vert.as_const())?
        .get(vertex)
        .ok_or(SourceHeapError::PointerOutOfBounds)?
        .iedge;
    usize::try_from(
        *heap
            .slice(iedge.as_const())?
            .get(neighbor_order)
            .ok_or(SourceHeapError::PointerOutOfBounds)?,
    )
    .map_err(|_| SourceHeapError::PointerOutOfBounds)
}

