        let mut mixed_heap = SourceHeap::default();
        let mut mixed = vec![carbon(), carbon(), carbon()];
        mixed[0].valence = 1;
        mixed[0].neighbor[0] = 1;
        mixed[0].bond_type[0] = BOND_TYPE_ALTERN as u8;
