    #[test]
    fn source_port__ichirvr2__setstereobondtypefor0dparity__line_790() {
        fn carbon() -> inp_ATOM {
            inp_ATOM {
                elname: [b'C' as i8, 0, 0, 0, 0, 0],
                ..inp_ATOM::default()
            }
        }

        let mut direct = vec![carbon(), carbon()];
        direct[0].valence = 1;
        direct[0].neighbor[0] = 1;
        direct[0].bond_type[0] = BOND_TYPE_SINGLE as u8;
        direct[0].chem_bonds_valence = 1;
        direct[0].sb_ord[0] = 0;
        direct[0].sb_parity[0] = 1;
        direct[1].valence = 1;
        direct[1].neighbor[0] = 0;
        direct[1].bond_type[0] = BOND_TYPE_SINGLE as u8;
        direct[1].chem_bonds_valence = 1;
        direct[1].sb_ord[0] = 0;
        direct[1].sb_parity[0] = 2;
        assert_eq!(SetStereoBondTypeFor0DParity(&mut direct, 0, 0), Ok(2));
        assert_eq!(
            (direct[0].bond_type[0], direct[1].bond_type[0]),
            (BOND_TYPE_STEREO as u8, BOND_TYPE_STEREO as u8)
        );
        assert_eq!((direct[0].chem_bonds_valence, direct[1].chem_bonds_valence), (1, 1));

        let mut chain = vec![carbon(), carbon(), carbon()];
        chain[0].valence = 1;
        chain[0].neighbor[0] = 1;
        chain[0].bond_type[0] = BOND_TYPE_SINGLE as u8;
        chain[0].chem_bonds_valence = 1;
        chain[0].sb_ord[0] = 0;
        chain[0].sb_parity[0] = 1;
        chain[1].valence = 2;
        chain[1].neighbor[..2].copy_from_slice(&[0, 2]);
        chain[1].bond_type[..2].copy_from_slice(&[1, 1]);
        chain[1].chem_bonds_valence = 2;
        chain[2].valence = 1;
        chain[2].neighbor[0] = 1;
        chain[2].bond_type[0] = BOND_TYPE_SINGLE as u8;
        chain[2].chem_bonds_valence = 1;
        chain[2].sb_ord[0] = 0;
        chain[2].sb_parity[0] = 2;
        assert_eq!(SetStereoBondTypeFor0DParity(&mut chain, 0, 0), Ok(3));
        assert_eq!(chain[0].bond_type[0], BOND_TYPE_DOUBLE as u8);
        assert_eq!(chain[1].bond_type[..2], [2, 2]);
        assert_eq!(chain[2].bond_type[0], BOND_TYPE_DOUBLE as u8);
        assert_eq!(
            (
                chain[0].chem_bonds_valence,
                chain[1].chem_bonds_valence,
                chain[2].chem_bonds_valence
            ),
            (2, 4, 2)
        );

        let mut second_slot = direct.clone();
        second_slot[1].valence = 2;
        second_slot[1].neighbor[..2].copy_from_slice(&[9, 0]);
        second_slot[1].sb_parity = [1, 2, 0];
        second_slot[1].sb_ord = [0, 1, 0];
        second_slot[0].bond_type[0] = 1;
        second_slot[1].bond_type[1] = 1;
        assert_eq!(SetStereoBondTypeFor0DParity(&mut second_slot, 0, 0), Ok(2));
        assert_eq!(second_slot[0].bond_type[0], BOND_TYPE_STEREO as u8);
        assert_eq!(second_slot[1].bond_type[1], BOND_TYPE_STEREO as u8);

        for blocked in [
            inp_ATOM {
                num_H: 1,
                ..chain[1].clone()
            },
            inp_ATOM {
                valence: 1,
                ..chain[1].clone()
            },
            inp_ATOM {
                endpoint: 1,
                ..chain[1].clone()
            },
            inp_ATOM {
                elname: [b'N' as i8, 0, 0, 0, 0, 0],
                ..chain[1].clone()
            },
        ] {
            let mut failed = chain.clone();
            failed[0].bond_type[0] = 1;
            failed[0].chem_bonds_valence = 1;
            failed[1] = blocked;
            failed[1].bond_type[..2].copy_from_slice(&[1, 1]);
            failed[1].chem_bonds_valence = 2;
            failed[1].sb_parity = [0; 3];
            failed[2].bond_type[0] = 1;
            failed[2].chem_bonds_valence = 1;
            let before = failed.clone();
            assert_eq!(SetStereoBondTypeFor0DParity(&mut failed, 0, 0), Ok(RI_ERR_SYNTAX));
            assert_eq!(failed, before);
        }

        let mut too_long = vec![carbon(), carbon(), carbon(), carbon()];
        too_long[0].valence = 1;
        too_long[0].neighbor[0] = 1;
        too_long[0].sb_ord[0] = 0;
        too_long[0].sb_parity[0] = 1;
        for index in 1..3 {
            too_long[index].valence = 2;
            too_long[index].neighbor[..2].copy_from_slice(&[(index - 1) as u16, (index + 1) as u16]);
        }
        too_long[3].valence = 1;
        too_long[3].neighbor[0] = 2;
        let before = too_long.clone();
        assert_eq!(SetStereoBondTypeFor0DParity(&mut too_long, 0, 0), Ok(RI_ERR_SYNTAX));
        assert_eq!(too_long, before);

        let mut partial = vec![carbon(), carbon(), carbon()];
        partial[0].valence = 1;
        partial[0].neighbor[0] = 1;
        partial[0].bond_type[0] = 1;
        partial[0].chem_bonds_valence = 1;
        partial[0].sb_ord[0] = 0;
        partial[0].sb_parity[0] = 1;
        partial[1].valence = 2;
        partial[1].neighbor[..2].copy_from_slice(&[0, 2]);
        partial[1].bond_type[..2].copy_from_slice(&[1, 1]);
        partial[1].chem_bonds_valence = 2;
        partial[2].valence = 0;
        partial[2].neighbor[0] = 1;
        partial[2].bond_type[0] = 1;
        partial[2].chem_bonds_valence = 1;
        partial[2].sb_ord[0] = 0;
        partial[2].sb_parity[0] = 2;
        assert_eq!(SetStereoBondTypeFor0DParity(&mut partial, 0, 0), Ok(RI_ERR_PROGR));
        assert_eq!(partial[0].bond_type[0], BOND_TYPE_DOUBLE as u8);
        assert_eq!(partial[1].bond_type, {
            let mut value = [0; 20];
            value[..2].copy_from_slice(&[2, 1]);
            value
        });
        assert_eq!(partial[2].bond_type[0], 1);

        assert_eq!(
            SetStereoBondTypeFor0DParity(&mut direct, -1, 0),
            Err(SourceHeapError::PointerOutOfBounds)
        );
        assert_eq!(
            SetStereoBondTypeFor0DParity(&mut direct, 0, i32::MAX),
            Err(SourceHeapError::PointerOutOfBounds)
        );
    }

    #[test]
    fn source_port__ichirvr2__set_bond_type__line_1614() {
        fn pair(first_type: u8, second_type: u8, first_chem: i8, second_chem: i8) -> Vec<inp_ATOM> {
            let mut atoms = vec![inp_ATOM::default(); 2];
            atoms[0].valence = 1;
            atoms[0].neighbor[0] = 1;
            atoms[0].bond_type[0] = first_type;
            atoms[0].chem_bonds_valence = first_chem;
            atoms[1].valence = 1;
            atoms[1].neighbor[0] = 0;
            atoms[1].bond_type[0] = second_type;
            atoms[1].chem_bonds_valence = second_chem;
            atoms
        }

        let mut atoms = pair(BOND_TYPE_SINGLE as u8, BOND_TYPE_DOUBLE as u8, 126, 125);
        assert_eq!(set_bond_type(&mut atoms, 0, 1, BOND_TYPE_TRIPLE as i32), Ok(0));
        assert_eq!((atoms[0].bond_type[0], atoms[1].bond_type[0]), (3, 3));
        assert_eq!((atoms[0].chem_bonds_valence, atoms[1].chem_bonds_valence), (-128, 127));

        for (previous, next) in [
            (0_u8, BOND_TYPE_DOUBLE as i32),
            (BOND_TYPE_ALTERN as u8, BOND_TYPE_DOUBLE as i32),
            (BOND_TYPE_SINGLE as u8, 0),
            (BOND_TYPE_SINGLE as u8, BOND_TYPE_ALTERN as i32),
            (BOND_TYPE_SINGLE as u8, 258),
        ] {
            let mut unchanged_chem = pair(previous, 99, 31, -47);
            assert_eq!(set_bond_type(&mut unchanged_chem, 0, 1, next), Ok(0));
            assert_eq!(
                (unchanged_chem[0].bond_type[0], unchanged_chem[1].bond_type[0]),
                (next as u8, next as u8)
            );
            assert_eq!(
                (
                    unchanged_chem[0].chem_bonds_valence,
                    unchanged_chem[1].chem_bonds_valence
                ),
                (31, -47)
            );
        }

        let mut negative = pair(BOND_TYPE_TRIPLE as u8, 1, i8::MIN, i8::MAX);
        assert_eq!(set_bond_type(&mut negative, 0, 1, -1), Ok(0));
        assert_eq!((negative[0].bond_type[0], negative[1].bond_type[0]), (u8::MAX, u8::MAX));
        assert_eq!(
            (negative[0].chem_bonds_valence, negative[1].chem_bonds_valence),
            (124, 123)
        );

        let mut one_sided = pair(1, 2, 7, 8);
        one_sided[1].neighbor[0] = 1;
        let before = one_sided.clone();
        assert_eq!(
            set_bond_type(&mut one_sided, 0, 1, BOND_TYPE_DOUBLE as i32),
            Ok(RI_ERR_SYNTAX)
        );
        assert_eq!(one_sided, before);

        let mut negative_valence = pair(1, 2, 7, 8);
        negative_valence[0].valence = -1;
        let before = negative_valence.clone();
        assert_eq!(
            set_bond_type(&mut negative_valence, 0, 1, BOND_TYPE_DOUBLE as i32,),
            Err(SourceHeapError::SourceIntegerOverflow)
        );
        assert_eq!(negative_valence, before);

        let mut single = vec![inp_ATOM::default()];
        assert_eq!(
            set_bond_type(&mut single, 0, 1, BOND_TYPE_SINGLE as i32),
            Err(SourceHeapError::PointerOutOfBounds)
        );
    }

