    #[test]
    fn source_port__ichirvr2__set_atom_0d_parity__line_1773() {
        fn center_with_neighbors(count: usize) -> Vec<inp_ATOM> {
            let mut atoms = vec![inp_ATOM::default(); count + 1];
            atoms[0].orig_at_number = 100;
            atoms[0].valence = count as i8;
            for index in 0..count {
                atoms[0].neighbor[index] = (index + 1) as u16;
                atoms[index + 1].orig_at_number = 101 + index as u16;
            }
            atoms
        }

        let mut three = center_with_neighbors(3);
        three[0].p_parity = 9;
        three[0].p_orig_at_num = [9; 4];
        assert_eq!(set_atom_0D_parity(&mut three, None, 4, 0, 0, 130), Ok(0));
        assert_eq!(three[0].p_orig_at_num, [100, 101, 102, 103]);
        assert_eq!(three[0].p_parity, -126);

        let mut four = center_with_neighbors(4);
        assert_eq!(set_atom_0D_parity(&mut four, None, 5, 0, 0, 2), Ok(0));
        assert_eq!(four[0].p_orig_at_num, [101, 102, 103, 104]);
        assert_eq!(four[0].p_parity, 2);

        let mut hydrogens = center_with_neighbors(2);
        hydrogens[0].num_H = 2;
        hydrogens.push(inp_ATOM {
            neighbor: {
                let mut value = [0; 20];
                value[0] = 0;
                value
            },
            orig_at_number: 201,
            ..inp_ATOM::default()
        });
        hydrogens.push(inp_ATOM {
            neighbor: {
                let mut value = [0; 20];
                value[0] = 0;
                value
            },
            orig_at_number: 202,
            ..inp_ATOM::default()
        });
        assert_eq!(set_atom_0D_parity(&mut hydrogens, None, 3, 2, 0, 1), Ok(0));
        assert_eq!(hydrogens[0].p_orig_at_num, [201, 202, 101, 102]);

        let mut missing = center_with_neighbors(2);
        missing[0].num_H = 2;
        missing[0].p_orig_at_num = [8; 4];
        missing.push(inp_ATOM {
            neighbor: {
                let mut value = [0; 20];
                value[0] = 0;
                value
            },
            orig_at_number: 211,
            ..inp_ATOM::default()
        });
        assert_eq!(set_atom_0D_parity(&mut missing, None, 3, 1, 0, 3), Ok(RI_ERR_PROGR));
        assert_eq!(missing[0].p_orig_at_num, [211, 8, 8, 8]);
        assert_eq!(missing[0].p_parity, 0);

        let mut wrong = center_with_neighbors(2);
        wrong[0].p_orig_at_num = [7; 4];
        assert_eq!(set_atom_0D_parity(&mut wrong, None, 3, 0, 0, 1), Ok(RI_ERR_PROGR));
        assert_eq!(wrong[0].p_orig_at_num, [7; 4]);

        let mut with_stereo = center_with_neighbors(3);
        let original_atoms = with_stereo.clone();
        let mut stereo = vec![inp_ATOM_STEREO::default(); 4];
        stereo[0].p_orig_at_num = [6; 4];
        assert_eq!(
            set_atom_0D_parity(&mut with_stereo, Some(&mut stereo), 4, 0, 0, 4),
            Ok(0)
        );
        assert_eq!(with_stereo, original_atoms);
        assert_eq!(stereo[0].p_orig_at_num, [100, 101, 102, 103]);
        assert_eq!(stereo[0].p_parity, 4);

        with_stereo[0].p_parity = 1;
        let before_stereo = stereo.clone();
        assert_eq!(
            set_atom_0D_parity(&mut with_stereo, Some(&mut stereo), 4, 0, 0, 2),
            Ok(0)
        );
        assert_eq!(stereo, before_stereo);
    }

